/**
 * One-off patch script. Run with: node scripts/patch-associations.js
 * Injects real association definitions into the models generated by generate-tables.js,
 * replacing the "// associations added per-model" placeholder comment.
 */
const fs = require("fs");
const path = require("path");

const MODELS_DIR = path.join(__dirname, "../src/models");

// modelName -> array of association lines (as raw JS, referencing `models`)
const ASSOCIATIONS = {
  Role: [
    `models.Role.hasMany(models.User, { foreignKey: "roleId", as: "users" });`,
    `models.Role.belongsToMany(models.Permission, { through: models.RolePermission, foreignKey: "roleId", otherKey: "permissionId", as: "permissions" });`,
  ],
  Permission: [
    `models.Permission.belongsToMany(models.Role, { through: models.RolePermission, foreignKey: "permissionId", otherKey: "roleId", as: "roles" });`,
  ],
  RolePermission: [
    `models.RolePermission.belongsTo(models.Role, { foreignKey: "roleId" });`,
    `models.RolePermission.belongsTo(models.Permission, { foreignKey: "permissionId" });`,
  ],
  User: [
    `models.User.belongsTo(models.Role, { foreignKey: "roleId", as: "role" });`,
    `models.User.hasOne(models.Student, { foreignKey: "userId", as: "studentProfile" });`,
    `models.User.hasMany(models.Blog, { foreignKey: "authorId", as: "blogs" });`,
    `models.User.hasMany(models.JobApplication, { foreignKey: "userId", as: "applications" });`,
  ],
  CourseCategory: [
    `models.CourseCategory.hasMany(models.Course, { foreignKey: "categoryId", as: "courses" });`,
  ],
  Course: [
    `models.Course.belongsTo(models.CourseCategory, { foreignKey: "categoryId", as: "category" });`,
    `models.Course.belongsTo(models.Instructor, { foreignKey: "instructorId", as: "instructor" });`,
    `models.Course.hasMany(models.CourseModule, { foreignKey: "courseId", as: "modules" });`,
    `models.Course.hasMany(models.Enrollment, { foreignKey: "courseId", as: "enrollments" });`,
    `models.Course.hasMany(models.Review, { foreignKey: "courseId", as: "reviews" });`,
    `models.Course.hasMany(models.Certificate, { foreignKey: "courseId", as: "certificates" });`,
  ],
  CourseModule: [
    `models.CourseModule.belongsTo(models.Course, { foreignKey: "courseId", as: "course" });`,
    `models.CourseModule.hasMany(models.Lesson, { foreignKey: "moduleId", as: "lessons" });`,
  ],
  Lesson: [
    `models.Lesson.belongsTo(models.CourseModule, { foreignKey: "moduleId", as: "module" });`,
  ],
  BlogCategory: [
    `models.BlogCategory.hasMany(models.Blog, { foreignKey: "categoryId", as: "blogs" });`,
  ],
  Blog: [
    `models.Blog.belongsTo(models.BlogCategory, { foreignKey: "categoryId", as: "category" });`,
    `models.Blog.belongsTo(models.User, { foreignKey: "authorId", as: "author" });`,
  ],
  SuccessStory: [
    `models.SuccessStory.belongsTo(models.Student, { foreignKey: "studentId", as: "student" });`,
  ],
  Job: [
    `models.Job.belongsTo(models.HiringPartner, { foreignKey: "companyId", as: "company" });`,
    `models.Job.belongsTo(models.CareerCategory, { foreignKey: "categoryId", as: "category" });`,
    `models.Job.hasMany(models.JobApplication, { foreignKey: "jobId", as: "applications" });`,
  ],
  JobApplication: [
    `models.JobApplication.belongsTo(models.Job, { foreignKey: "jobId", as: "job" });`,
    `models.JobApplication.belongsTo(models.ApplicationStatus, { foreignKey: "statusId", as: "status" });`,
    `models.JobApplication.belongsTo(models.User, { foreignKey: "userId", as: "applicant" });`,
  ],
  HiringPartner: [
    `models.HiringPartner.hasMany(models.Job, { foreignKey: "companyId", as: "jobs" });`,
  ],
  Instructor: [
    `models.Instructor.hasMany(models.Course, { foreignKey: "instructorId", as: "courses" });`,
  ],
  Student: [
    `models.Student.belongsTo(models.User, { foreignKey: "userId", as: "user" });`,
    `models.Student.belongsTo(models.City, { foreignKey: "cityId", as: "city" });`,
    `models.Student.hasMany(models.Enrollment, { foreignKey: "studentId", as: "enrollments" });`,
    `models.Student.hasMany(models.Certificate, { foreignKey: "studentId", as: "certificates" });`,
  ],
  Enrollment: [
    `models.Enrollment.belongsTo(models.Student, { foreignKey: "studentId", as: "student" });`,
    `models.Enrollment.belongsTo(models.Course, { foreignKey: "courseId", as: "course" });`,
  ],
  Certificate: [
    `models.Certificate.belongsTo(models.Student, { foreignKey: "studentId", as: "student" });`,
    `models.Certificate.belongsTo(models.Course, { foreignKey: "courseId", as: "course" });`,
  ],
  Review: [
    `models.Review.belongsTo(models.Course, { foreignKey: "courseId", as: "course" });`,
    `models.Review.belongsTo(models.Student, { foreignKey: "studentId", as: "student" });`,
  ],
  MenuItem: [
    `models.MenuItem.belongsTo(models.Menu, { foreignKey: "menuId", as: "menu" });`,
    `models.MenuItem.belongsTo(models.MenuItem, { foreignKey: "parentId", as: "parent" });`,
    `models.MenuItem.hasMany(models.MenuItem, { foreignKey: "parentId", as: "children" });`,
  ],
  Menu: [
    `models.Menu.hasMany(models.MenuItem, { foreignKey: "menuId", as: "items" });`,
  ],
  SEO: [
    `models.SEO.belongsTo(models.Page, { foreignKey: "pageId", as: "page" });`,
  ],
  Page: [
    `models.Page.hasOne(models.SEO, { foreignKey: "pageId", as: "seo" });`,
  ],
  CareerCategory: [
    `models.CareerCategory.hasMany(models.Job, { foreignKey: "categoryId", as: "jobs" });`,
    `models.CareerCategory.hasMany(models.CareerOpportunity, { foreignKey: "categoryId", as: "opportunities" });`,
  ],
  CareerOpportunity: [
    `models.CareerOpportunity.belongsTo(models.CareerCategory, { foreignKey: "categoryId", as: "category" });`,
  ],
  ApplicationStatus: [
    `models.ApplicationStatus.hasMany(models.JobApplication, { foreignKey: "statusId", as: "applications" });`,
  ],
  Country: [
    `models.Country.hasMany(models.State, { foreignKey: "countryId", as: "states" });`,
  ],
  State: [
    `models.State.belongsTo(models.Country, { foreignKey: "countryId", as: "country" });`,
    `models.State.hasMany(models.City, { foreignKey: "stateId", as: "cities" });`,
  ],
  City: [
    `models.City.belongsTo(models.State, { foreignKey: "stateId", as: "state" });`,
    `models.City.hasMany(models.Student, { foreignKey: "cityId", as: "students" });`,
  ],
};

let patched = 0;
Object.entries(ASSOCIATIONS).forEach(([modelName, lines]) => {
  const filePath = path.join(MODELS_DIR, `${modelName}.js`);
  if (!fs.existsSync(filePath)) {
    console.warn(`Skipped ${modelName}: file not found`);
    return;
  }
  let content = fs.readFileSync(filePath, "utf8");
  const placeholder = `// associations added per-model in src/models/${modelName}.js`;
  if (!content.includes(placeholder)) {
    console.warn(`Skipped ${modelName}: placeholder not found (already patched?)`);
    return;
  }
  const body = lines.map((l) => `      ${l}`).join("\n");
  content = content.replace(placeholder, body);
  fs.writeFileSync(filePath, content);
  patched += 1;
});

console.log(`Patched associations into ${patched} models.`);
